require_once __DIR__.'/functions.php';require_login();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT p.*,l.loan_code,l.total_due,l.principal,l.interest_amount,b.name borrower,b.phone FROM payments p JOIN loans l ON l.id=p.loan_id JOIN borrowers b ON b.id=l.borrower_id WHERE p.id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)exit('Bukti pembayaran tidak ditemukan.');$paid=loan_paid($pdo,(int)$r['loan_id']);$left=max(0,(float)$r['total_due']-$paid);?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Bukti Pembayaran</title><style>body{font:14px Arial;color:#222;max-width:680px;margin:35px auto;padding:20px}.receipt{border:1px solid #ddd;padding:28px}.center{text-align:center}.line{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px dashed #ddd}.muted{color:#777;font-size:12px}@media print{button{display:none}body{margin:0}}</style></head><body><div class="receipt"><div class="center"><h2>BUKTI PEMBAYARAN</h2><b>PINJAMAN JATUH TEMPO</b><p class="muted">Simpan bukti pembayaran ini.</p></div><hr><div class="line"><span>No. pembayaran</span><b><?=e($r['payment_code'])?></b></div><div class="line"><span>Kode pinjaman</span><b><?=e($r['loan_code'])?></b></div><div class="line"><span>Nama peminjam</span><b><?=e($r['borrower'])?></b></div><div class="line"><span>Tanggal pembayaran</span><b><?=date('d/m/Y',strtotime($r['payment_date']))?></b></div><div class="line"><span>Jumlah dibayarkan</span><b>Rp <?=number_format($r['amount'],0,',','.')?></b></div><div class="line"><span>Total tagihan</span><b>Rp <?=number_format($r['total_due'],0,',','.')?></b></div><div class="line"><span>Total sudah dibayar</span><b>Rp <?=number_format($paid,0,',','.')?></b></div><div class="line"><span>Sisa tagihan</span><b>Rp <?=number_format($left,0,',','.')?></b></div><p>Catatan: <?=e($r['notes'])?></p><p class="center muted">Terima kasih.</p></div><p class="center"><button onclick="window.print()">Cetak bukti</button></p></body></html>
